// One PDF per request. The model needs it as base64 text.
const item = $input.first();
const file = item.binary?.file;
if (!file) {
  throw new Error('No PDF found. Send it as multipart form field "file".');
}
const buffer = await this.helpers.getBinaryDataBuffer(0, 'file');
// Keep the binary so the next node can hash the file.
return [{
  json: { file_name: file.fileName, pdf_base64: buffer.toString('base64') },
  binary: item.binary,
}];

