parameters.jsCode:
// Business rules. Each rule gets the extracted invoice and returns a short code or null.
const TEXT_FIELDS = ['vendor_name', 'vendor_tax_id', 'invoice_number', 'invoice_date', 'due_date', 'currency'];
const NUMBER_FIELDS = ['subtotal', 'tax', 'total'];
const cents = (value) => Math.round(Number(value) * 100);

function missingField(inv) {
  const emptyText = TEXT_FIELDS.some((key) => !String(inv[key] ?? '').trim());
  const emptyNumber = NUMBER_FIELDS.some((key) => typeof inv[key] !== 'number');
  const noLines = !Array.isArray(inv.line_items) || inv.line_items.length === 0;
  return emptyText || emptyNumber || noLines ? 'missing_field' : null;
}

function sumMismatch(inv) {
  if (!Array.isArray(inv.line_items) || NUMBER_FIELDS.some((key) => typeof inv[key] !== 'number')) {
    return null; // missing_field already covers this
  }
  const lines = inv.line_items.reduce((sum, line) => sum + cents(line.amount ?? 0), 0);
  const off = (a, b) => Math.abs(a - b) > 1; // 0.01 tolerance
  return off(lines, cents(inv.subtotal)) || off(cents(inv.subtotal) + cents(inv.tax), cents(inv.total))
    ? 'sum_mismatch'
    : null;
}

function isRealDate(text) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text ?? '')) return false;
  const parsed = new Date(`${text}T00:00:00Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === text;
}

function badDates(inv) {
  if (!isRealDate(inv.invoice_date) || !isRealDate(inv.due_date)) return 'bad_dates';
  return inv.due_date < inv.invoice_date ? 'bad_dates' : null;
}

function badTaxId(inv) {
  const id = String(inv.vendor_tax_id ?? '').trim();
  return /^\d{2}-\d{7}$/.test(id) || /^GB\d{9}$/.test(id) ? null : 'bad_tax_id';
}

const RULES = [missingField, sumMismatch, badDates, badTaxId];

const response = $input.first().json;
const call = (response.content ?? []).find((block) => block.type === 'tool_use' && block.name === 'record_invoice');
const extracted = call ? call.input : {};
// No tool call means nothing was read, which is a missing field from the bookkeeper's view.
const issues = call ? RULES.map((rule) => rule(extracted)).filter(Boolean) : ['missing_field'];
const file = $('Hash file').first().json;

return [{
  json: {
    file_name: file.file_name,
    file_hash: file.file_hash,
    extracted,
    issues,
    stop_reason: response.stop_reason,
  },
}];

