// Join the rule results with the duplicate and vendor lookups. One invoice per run.
const WORDS = {
  missing_field: 'a required field is empty',
  sum_mismatch: 'line items or totals do not add up',
  bad_dates: 'due date is missing, invalid or before the invoice date',
  bad_tax_id: 'tax id is not a valid EIN or UK VAT number',
  duplicate: 'this invoice number was already posted for this vendor',
  unknown_vendor: 'vendor is not in QuickBooks',
};
const checked = $('Validate').first().json;
const vendor = $input.first().json;
const issues = [...checked.issues];
if ($('Duplicate?').first().json.duplicate === true) issues.push('duplicate');
if (!vendor.Id) issues.push('unknown_vendor');

const inv = checked.extracted;
const alertText = [
  checked.file_name,
  inv.vendor_name || 'no vendor name',
  inv.invoice_number || 'no invoice number',
  issues.map((code) => WORDS[code]).join('; '),
].join(' | ');

return [{
  json: {
    ...checked,
    issues,
    vendor_id: vendor.Id ?? null,
    vendor_currency: vendor.CurrencyRef?.value ?? null,
    alert_text: alertText,
  },
}];

